export function filterHelpGuides({ role = 'student', group = 'all', query = '' } = {}) {
  const terms = String(query).trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
  return HELP_GUIDES.filter(item => (item.role === role || item.role === 'common') && (group === 'all' || item.group === group) && terms.every(term => [item.title, item.summary, item.group, ...item.steps].join(' ').toLocaleLowerCase().includes(term)));
}
